const theme=new URLSearchParams(location.search).get('theme')==='files'?'files':'motion';
document.body.classList.add(theme);document.querySelector(`[data-direction="${theme}"]`).classList.add('active');
const students=[{name:'Adebayo Adeyemi',id:'EEE/2022/001',level:'400',initials:'AA',status:'Reviewed'},{name:'Chidinma Okafor',id:'EEE/2021/014',level:'500',initials:'CO',status:'In review'},{name:'Tomiwa Balogun',id:'EEE/2023/028',level:'300',initials:'TB',status:'Reviewed'},{name:'Fatima Ibrahim',id:'EEE/2022/043',level:'400',initials:'FI',status:'Reviewed'},{name:'Emeka Nwosu',id:'EEE/2024/019',level:'200',initials:'EN',status:'In review'},{name:'Zainab Bello',id:'EEE/2025/007',level:'100',initials:'ZB',status:'Reviewed'}];
const header=`<header class="topnav"><a class="brand" href="index.html?theme=${theme}"><span class="brand-mark">↯</span><span>OBAFEMI AWOLOWO UNIVERSITY<br><b>Electrical & Electronic Engineering</b></span></a><nav class="links" aria-label="Main navigation"><a href="#workspace">Student records</a><a href="#modules">Department</a><button class="pill" id="staff">Staff workspace ↗</button></nav></header>`;
const tools=`<div class="tools"><input class="search" id="search" type="search" placeholder="Search a name or matric number…" aria-label="Search students"><select id="level" aria-label="Filter by level"><option value="">All levels</option>${[100,200,300,400,500].map(x=>`<option value="${x}">${x} level</option>`).join('')}</select><span class="eyebrow" id="count"></span></div><div class="student-list" id="students"></div>`;
const footer=`<footer class="foot"><span>OAU · EEE DEPARTMENT<br>Student records & identification system</span><span>Design exploration / ${theme==='files'?'02':'01'}<br>Demo records only · No backend connection</span><a href="?theme=${theme==='files'?'motion':'files'}">Try the other direction ↗</a></footer>`;
const orbit=`<div class="orbit" aria-hidden="true"><svg viewBox="0 0 240 240"><circle cx="120" cy="120" r="105"/><circle cx="120" cy="120" r="74"/><circle cx="120" cy="120" r="35"/><path d="M0 120H85M155 120H240M120 0V85M120 155V240M45 45L95 95M145 145L195 195M45 195L95 145M145 95L195 45"/><circle class="dot" cx="120" cy="15" r="7"/><circle class="dot" cx="195" cy="195" r="6"/></svg></div>`;
if(theme==='motion'){
document.querySelector('#app').innerHTML=`<div class="shell">${header}<section class="hero"><span class="eyebrow">The department, connected. / OAU EEE</span>${orbit}<h1>Good records.<br><em>Great possibilities.</em></h1><div class="hero-bottom"><p>A connected home for our students, academic records, and the people moving engineering forward.</p><a class="pill orange" href="#workspace">Explore student records <span>↗</span></a><button class="pill" id="motion-toggle" aria-pressed="false">Pause motion Ⅱ</button></div></section></div><div class="ticker" aria-hidden="true"><div class="ticker-track">${Array(4).fill('<span>PEOPLE × POSSIBILITIES</span><span>ENGINEERING THE NEXT</span><span>ONE DEPARTMENT. CONNECTED.</span>').join('')}</div></div><div class="shell"><section id="modules"><div class="section-head"><div><span class="eyebrow">01 / Your workspace</span><h2>Everything in its place.</h2></div><span class="eyebrow">Choose a starting point ↙</span></div><div class="modules">${[['Student records','Find the people behind the matric numbers. Browse profiles by level and cohort.','records'],['Academic files','A clearer view of results, course history, and outstanding requirements.','academic'],['Import & review','Stage incoming records. Resolve questions before accepting changes.','imports'],['Adviser inbox','Keep departmental conversations connected to the right people.','messages'],['Identity terminal','Explore the separate identity workflow and terminal outcomes.','identity'],['Department at a glance','A small overview of the people and files in this demonstration.','overview']].map((m,i)=>`<button class="module reveal ${i===2?'orange':''}" data-module="${m[2]}"><span class="number">(0${i+1})</span><span class="arrow">↗</span><h3>${m[0]}</h3><p>${m[1]}</p></button>`).join('')}</div></section><section class="workspace" id="workspace"><div class="section-head"><div><span class="eyebrow">02 / The people</span><h2>A department of possibilities.</h2></div><span class="eyebrow">Sample student directory</span></div>${tools}</section>${footer}</div>`;
document.querySelector('#motion-toggle').onclick=e=>{const paused=document.body.classList.toggle('motion-paused');e.currentTarget.setAttribute('aria-pressed',paused);e.currentTarget.textContent=paused?'Resume motion ▷':'Pause motion Ⅱ'};
}else{
const folders=[['Student records','A place for every student.','students','#c5d6bc','5%'],['Academic files','Results, courses & the bigger picture.','academic','#e7dfcf','35%'],['Import & review','Incoming records, carefully organised.','imports','#d6dec9','60%'],['Adviser inbox','Conversations worth keeping.','messages','#e8dfc9','20%'],['Department notes','The essentials, all together.','overview','#b8cdb1','48%']];
document.querySelector('#app').innerHTML=`<div class="shell">${header}<section class="hero"><span class="eyebrow">Welcome to the department's filing room</span><div class="stamp">OAU EEE<br>PEOPLE & RECORDS<br>FILED WITH CARE</div><h1>A little order.<br><em>A lot of possibility.</em></h1><div class="hero-bottom"><p>Pull up a chair. Find a student, open a file, or pick up where you left off. Everything has a place here.</p><a class="pill orange" href="#workspace">Open the cabinet <span>↘</span></a><span class="corner-star" aria-hidden="true">✳</span></div></section><section class="cabinet" id="workspace" aria-label="Department file cabinet">${folders.map((f,i)=>`<div class="folder-section" id="${i===0?'modules':'folder-'+f[2]}"><button class="folder-tab" id="tab-${f[2]}" aria-expanded="${i===0}" aria-controls="panel-${f[2]}" data-folder="${f[2]}" style="--paper:${f[3]};--offset:${f[4]}"><span class="folder-label">EEE / 0${i+1}</span><strong>${f[0]}</strong><span class="folder-description">${f[1]}</span><span class="folder-symbol">${i===0?'−':'+'}</span></button><div class="folder-panel ${i===0?'open':''}" id="panel-${f[2]}" role="region" aria-labelledby="tab-${f[2]}">${i===0?`<div class="section-head" style="padding-top:0"><span class="eyebrow">Student index / sample files</span><span class="eyebrow">Click a name to open a file ↙</span></div>${tools}`:moduleContent(f[2])}</div></div>`).join('')}</section>${footer}</div>`;
document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);document.getElementById(b.getAttribute('aria-controls')).classList.toggle('open',open);b.querySelector('.folder-symbol').textContent=open?'−':'+'});
}
function moduleContent(key){const content={academic:['Academic files','Review academic history with the original context intact.','Select a student record to explore the sample file sections: biodata, course history, and review notes. Missing results remain unknown until reviewed.'],imports:['Incoming tray','Every new record starts with a careful review.','Demo batch: EEE_SAMPLE_01 · 6 synthetic rows · 2 awaiting review. This prototype illustrates the review queue; it does not upload or accept records.'],messages:['Adviser inbox','A quieter place for departmental conversations.','Sample message · Record review follow-up: Please review the two pending demo files in the student index. No messages are sent from this prototype.'],identity:['Identity terminal','Connected, with a clear boundary.','Demo terminal: idle. Identity verification is a separate workflow. A match does not automatically open academic records.'],overview:['Department notes','A small snapshot of this filing room.','This study contains six synthetic student files across five levels. Four files are marked reviewed; two are awaiting review.']};const c=content[key]||content.overview;return `<span class="eyebrow">DEPARTMENT / SAMPLE WORKSPACE</span><h2>${c[0]}</h2><p>${c[1]}</p><div class="note">${c[2]}</div><div class="summary-grid" style="margin-top:20px"><div class="summary-card">Demo files<strong>06</strong>Synthetic student records</div><div class="summary-card">Reviewed<strong>04</strong>Sample review status</div><div class="summary-card">In review<strong>02</strong>Awaiting a second look</div></div>`}
function show(content){document.querySelector('#record-content').innerHTML=content;document.querySelector('#record').showModal()}
function renderStudents(){const q=document.querySelector('#search').value.trim().toLowerCase(),level=document.querySelector('#level').value;const list=students.filter(s=>(!level||s.level===level)&&`${s.name} ${s.id}`.toLowerCase().includes(q));document.querySelector('#count').textContent=`${list.length} files`;document.querySelector('#students').innerHTML=list.length?list.map(s=>`<button class="student-row" data-student="${s.id}"><span class="avatar">${s.initials}</span><span>${s.name}<small>Electrical & Electronic Engineering</small></span><span class="matric">${s.id}<small>Matric number</small></span><span class="level">${s.level}<small>Level</small></span><span class="status">${s.status}</span><span>↗</span></button>`).join(''):'<div class="empty">No files match that search. Try another name or level.</div>';document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{const s=students.find(s=>s.id===b.dataset.student);show(`<span class="eyebrow">Student file / synthetic record</span><h2>${s.name}</h2><dl><dt>Matric number</dt><dd>${s.id}</dd><dt>Level</dt><dd>${s.level}</dd><dt>Department</dt><dd>Electrical & Electronic Engineering</dd><dt>Review status</dt><dd>${s.status}</dd></dl><div class="note">Sample file sections: biodata, academic history, and review notes.<br>Academic results have not been added to this design study.</div><p class="eyebrow">Demo record · No personal or live academic data</p>`)});}
document.querySelector('#search').addEventListener('input',renderStudents);document.querySelector('#level').addEventListener('change',renderStudents);renderStudents();
document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{if(b.dataset.module==='records'){document.querySelector('#workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#search').focus({preventScroll:true})}else show(moduleContent(b.dataset.module))});
document.querySelector('#staff').onclick=()=>show(`<span class="eyebrow">Staff workspace / design preview</span><h2>A home for the department.</h2><p>Explore student records, academic files, incoming imports, and adviser conversations using the sample workspace.</p><div class="note">This prototype uses synthetic records. Staff authentication and backend integration belong to the implementation stage.</div>`);
document.querySelector('#record').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
